    private string CopiaDeDatos()
    {
        var raiz = Path.Combine(Path.GetTempPath(), "tutorflow-invalidos-" + Guid.NewGuid().ToString("N"));
        _temporales.Add(raiz);
        foreach (var sub in new[] { "api", "reglamento" })
        {
