        [
          { "id": "T-E1", "nombre": "Alicia Prueba Uno", "programa": "Programa Alfa", "semestre": 2 },
          { "id": "T-E9", "nombre": "Registro Incompleto Nueve", "programa": "Programa Alfa" }
